coordinates = {value: index + 1 for index, value in enumerate(sorted(set(values)))}
tree = [(0, 0)] * (len(coordinates) + 1)

def merge(left, right):
    if left[0] != right[0]:
        return left if left[0] > right[0] else right
    return (left[0], (left[1] + right[1]) % MOD)

def query(index):
    result = (0, 0)
    while index:
        result = merge(result, tree[index])
        index -= index & -index
    return result

def update(index, value):
    while index < len(tree):
        tree[index] = merge(tree[index], value)
        index += index & -index

for value in values:
    index = coordinates[value]
    length, count = query(index - 1)
    update(index, (length + 1, count if length else 1))
print(*query(len(coordinates)))

